"use strict";
const ways = {
  "by +": text => text.slice(0, 2) + text.slice(2),
  "by join": text => [...text].join(""),
  "by slice": text => ("<" + text + ">").slice(1, -1),
  "by a template": text => `${text.slice(0, 1)}${text.slice(1)}`,
  "by a row of +": text => {
    let made = "";
    for (const letter of text) made += letter;
    return made;
  },
};
exports.storeEqualTexts = () =>
  Object.entries(ways).map(([way, make]) => {
    const said = [];
    for (const name of ["platform", "arch"]) {
      try {
        process[name] = make(process[name]);
        said.push(name + " " + Reflect.set(process, name, make(process[name])));
      } catch (error) {
        said.push(name + " throws " + error.constructor.name);
      }
    }
    return way + ": " + said.join(", ");
  });
